#include <stdint.h>
#include <stddef.h>

#define PARITY_NONE 0
#define PARITY_EVEN 1
#define PARITY_ODD  2

static int count_ones(const uint8_t *p, int n)
{
    int ones = 0;
    for (int i = 0; i < n; i++) {
        if (p[i] == 1) {
            ones++;
        }
    }
    return ones;
}

int uart_frame_check(const uint8_t *bytes, int len, int data_bits, int parity)
{
    if (bytes == NULL || len <= 0 || data_bits < 5 || data_bits > 9) {
        return -1;
    }
    if (parity != PARITY_NONE && parity != PARITY_EVEN && parity != PARITY_ODD) {
        return -1;
    }

    int has_parity = (parity != PARITY_NONE) ? 1 : 0;
    int expect_len = 1 + data_bits + has_parity + 1;

    if (len != expect_len) {
        return 0;
    }
    if (bytes[0] != 0 || bytes[expect_len - 1] != 1) {
        return 0;
    }
    for (int i = 0; i < expect_len; i++) {
        if (bytes[i] != 0 && bytes[i] != 1) {
            return 0;
        }
    }

    if (has_parity) {
        int ones = count_ones(&bytes[1], data_bits) + (int)bytes[1 + data_bits];
        if (parity == PARITY_EVEN) {
            if ((ones & 1) != 0) {
                return 0;
            }
        } else {
            if ((ones & 1) != 1) {
                return 0;
            }
        }
    }
    return 1;
}
